// Regenerates src/relay-bundle.generated.ts: the in-sandbox relay
// (src/entry.ts) bundled, minified, gzipped and base64-encoded, so hosts
// without a filesystem (Cloudflare Workers) can install it too.
//   node packages/sandbox-egress/scripts/build-relay-bundle.mjs
// packages/sandbox-port-kit/test/relay-bundle.test.ts fails when it is stale.
import { createHash } from "node:crypto";
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { gzipSync } from "node:zlib";
import { build } from "esbuild";

export async function bundleRelaySource() {
  const result = await build({
    entryPoints: [fileURLToPath(new URL("../src/entry.ts", import.meta.url))],
    bundle: true,
    platform: "node",
    format: "cjs",
    target: "node20",
    minify: true,
    keepNames: true,
    legalComments: "none",
    write: false,
    logLevel: "warning",
  });
  return result.outputFiles[0].text;
}

export function relaySha256(source) {
  return createHash("sha256").update(source).digest("hex");
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const source = await bundleRelaySource();
  const encoded = gzipSync(Buffer.from(source), { level: 9 }).toString("base64");
  writeFileSync(
    fileURLToPath(new URL("../src/relay-bundle.generated.ts", import.meta.url)),
    [
      "// Generated by scripts/build-relay-bundle.mjs from src/entry.ts. Do not edit.",
      `export const RELAY_BUNDLE_SHA256 = ${JSON.stringify(relaySha256(source))};`,
      `export const RELAY_BUNDLE_GZIP_BASE64 = ${JSON.stringify(encoded)};`,
      "",
    ].join("\n"),
  );
  console.log(`relay bundle: ${source.length} bytes, ${encoded.length} base64 bytes`);
}
